		}
		const { csrf_token } = body;
		request.post(`${nconf.get('url')}/login`, {
			form: {
				username: username,
				password: password,
			},
			json: true,
			jar: jar,
			headers: {
				'x-csrf-token': csrf_token,
			},
		}, (err, res, body) => {
			if (err) {
				return callback(err || new Error('[[error:invalid-response]]'));
			}
